import {SUBJECTS,TOPICS,GUIDES,WRITING,PROFILE} from './content.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2z',book:'M12 5c-3-3-7-3-10-1v15c4-2 7-1 10 1m0-15c3-3 7-3 10-1v15c-4-2-7-1-10 1V5z',check:'M4 12l5 5L20 6',leaf:'M4 20C4 6 12 4 21 3c0 12-4 17-13 17m-4 0L16 8',clock:'M12 7v5l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',chart:'M4 20V10m7 10V4m7 16v-7M2 22h20',music:'M9 18V5l12-2v13M9 5v5l12-2M9 18c0 4-7 4-7 0s7-4 7 0m12-2c0 4-7 4-7 0s7-4 7 0',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',arrow:'M4 12h16m-6-6 6 6-6 6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3l1-2h4l1 2 3 2 2 1 2 3-1 3 1 3-2 3-3 1-2 3H9l-2-3-3-1-2-3 1-3-1-3 2-3 3-1z',note:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',play:'m8 4 12 8-12 8z',pause:'M8 4v16M16 4v16',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
const icon=(n,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`;
const subjectIcon={japanese:'あ',math:'∫',physics:'λ',chemistry:'H₂'};
let state,bank=[],assets=[],page='today',filter='all',query='',selectedDate,session=null,reportText='',musicPlaying=false,ducks=new Set(),pendingCoach=null,lastFocused=null;
const bgm=$('#bgm');bgm.volume=Number(localStorage.getItem('eju-volume')??.22);
let track=localStorage.getItem('eju-track')||'music-01';
const toast=msg=>{const e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3500);};
async function request(url,options){const r=await fetch(url,options);const x=await r.json();if(!r.ok)throw Error(x.error||'操作失败');return x;}
async function act(data){state=await request('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});render();return state;}
function safely(fn){return async(...args)=>{try{await fn(...args);}catch(e){toast(e.message);}};}
const on=(s,ev,fn)=>$(s)?.addEventListener(ev,safely(fn));
const plan=()=>state.plans[state.today];
const add=(d,n)=>new Date(Date.parse(d+'T12:00:00Z')+n*86400000).toISOString().slice(0,10);
const sum=a=>a.reduce((x,y)=>x+y,0);
const qby=id=>bank.find(q=>q.id===id);
function dueQuestions(){return (state.reviewQueue||[]).filter(r=>r.questionId).map(r=>qby(r.questionId)).filter(Boolean);}
function landscape(){return `<svg class="landscape" viewBox="0 0 450 260" fill="none" aria-hidden="true"><circle cx="308" cy="78" r="45" fill="#f8f5df"/><path d="M15 260 225 51l205 209" fill="#cfdbbc"/><path d="m165 260 178-163 144 163" fill="#b7c9a9"/><path d="M0 225q120-45 234 0t216-12v47H0" fill="#91ac91"/><path d="M120 260q65-54 167-37t163-35v72" fill="#708f79"/><path d="M255 257q-6-30 17-56-4 24-17 56m-1-18q-30-6-25-30 19 8 25 30" fill="#406653"/><path d="M311 205v-61m0 19q-32 2-23-32 23 9 23 32m0 18q34 0 34-34-31 5-34 34" stroke="#6e8964" stroke-width="3" fill="#a6be94"/><path d="M28 171h53m-15-4 9 4-9 4m75-95 10-5 10 5" stroke="#90a780" stroke-width="2"/></svg>`;}
function shell(){const nav=[['today','home','今日学习'],['plan','calendar','备考路线'],['practice','book','每日题库'],['review','note','迁移复习'],['guides','sun','知识讲解'],['report','chart','复盘与汇报'],['rewards','leaf','成长花园'],['settings','settings','资料与备份']];return `<div class="layout"><aside class="sidebar"><div class="brand"><img src="/assets/icon.svg" alt=""><div><div class="brand-name">澄学</div><small>EJU 630</small></div></div><nav class="nav" aria-label="主导航">${nav.map(([p,i,t])=>`<button data-page="${p}" class="${page===p?'active':''}">${icon(i)}<span>${t}</span>${p==='review'&&dueQuestions().length?`<span class="n">${dueQuestions().length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-note"><span class="sidebar-orbit">✧</span><p>2026.11.08</p></div></aside><main class="main"><div class="topbar"><span class="crumb">我的学习空间 / ${nav.find(x=>x[0]===page)?.[2]}</span><span class="mobile-brand">澄学</span><div class="row"><span class="small muted">${state.today.replaceAll('-','.')} <span class="tiny">${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',weekday:'long'}).format(new Date(state.today+'T12:00:00+08:00'))}</span></span></div></div><div id="view"></div></main></div><div class="musicbar"><div class="music-art">${icon('music')}</div><div class="music-meta"><strong>专注钢琴</strong></div><button id="music-toggle" class="circle" aria-label="${musicPlaying?'暂停背景音乐':'播放背景音乐'}">${icon(musicPlaying?'pause':'play')}</button><select id="music-track" aria-label="背景音乐曲目">${assets.filter(a=>a.subject==='music'&&a.available).map(a=>`<option value="${a.id}" ${track===a.id?'selected':''}>${a.title}</option>`).join('')}</select><input id="volume" type="range" min="0" max="0.6" step="0.01" value="${Number(localStorage.getItem('eju-volume')??.22)}" aria-label="音乐音量"><button class="linkbutton small" id="music-credit">来源与授权</button><span class="status" id="music-status">${ducks.size?'听力播放中，背景音乐已静音':''}</span></div>`;}
function header(title,sub,button=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`;}
function taskHTML(t,interactive=true){const r=state.records[t.id],official=t.questionIds.filter(id=>qby(id)?.official).length;return `<div class="task ${r?.completed?'done':''}"><div class="subject-icon ${t.subject}">${subjectIcon[t.subject]}</div><div class="task-body"><h3>${esc(t.title)}</h3><details class="task-method"><summary>练习方法</summary><p>${esc(t.method)}</p></details><div class="task-footer"><span class="tag">${t.minutes} 分钟</span>${t.topic==='writing'?'<span class="tag">保存作文原文</span>':`<span class="tag">${t.questionIds.length} 项练习${official?` · ${official} 项真题`:''}</span>`}${r?`<span class="tag">已记录 ${r.minutes} 分钟</span>`:''}</div></div>${interactive?`<div class="task-action"><button class="btn small ${r?.completed?'soft':''}" data-study="${t.id}">${r?.completed?'再练习':'开始学习'} ${icon('arrow')}</button><button class="linkbutton" data-complete="${t.id}">${r?'修改记录':'记录成果'}</button></div>`:''}</div>`;}
function timerCard(){return `<div class="card timer"><div class="card-head"><h3>${icon('clock')} 专注一会儿</h3><select id="timer-duration" class="text" aria-label="专注时长" style="width:83px;padding:4px"><option value="25">25 分钟</option><option value="40">40 分钟</option><option value="50">50 分钟</option><option value="5">5 分钟休息</option></select></div><div class="timer-ring"><div class="timer-face"><strong id="timer-clock">25:00</strong><small id="timer-label">一次只做一件事</small></div></div><div class="row" style="justify-content:center"><button id="timer-toggle" class="btn">开始专注</button><button id="timer-reset" class="btn line" aria-label="重置计时">重置</button></div></div>`;}
function todayView(){const p=plan(),done=p.tasks.filter(t=>state.records[t.id]?.completed).length,mins=sum(Object.values(state.records).filter(r=>r.date===state.today).map(r=>r.minutes)),remaining=Math.max(0,Math.ceil((Date.parse(PROFILE.examDate)-Date.parse(state.today))/86400000));const mode=localStorage.getItem('eju-wallpaper')||'motion';return `<section class="hero study-hero ${mode==='off'?'no-wallpaper':''}">${mode!=='off'?`<video id="wallpaper" class="wallpaper" muted loop playsinline preload="metadata" poster="/assets/wallpaper/haibara.jpg" src="/assets/wallpaper/haibara.mp4" aria-label="灰原哀动态壁纸"></video>`:landscape()}<div class="hero-text"><span class="hero-date">${state.today.slice(5).replace('-',' / ')} · 距 EJU ${remaining} 天</span><h1>今天，<br>只向前一小步。</h1><p>${p.stage} · ${p.budget} 分钟</p><button class="btn" id="continue">${session?'继续上次练习':'开始今天的学习'} ${icon('arrow')}</button></div><div class="wallpaper-control"><label for="wallpaper-mode">壁纸</label><select id="wallpaper-mode" aria-label="壁纸模式"><option value="motion" ${mode==='motion'?'selected':''}>动态</option><option value="still" ${mode==='still'?'selected':''}>静态</option><option value="off" ${mode==='off'?'selected':''}>关闭</option></select></div></section><div class="daily-strip"><div><strong>${done}<span> / ${p.tasks.length}</span></strong><span>今日任务</span></div><div><strong>${mins}<span> 分钟</span></strong><span>已学习</span></div><button data-page="rewards"><strong>${state.points}<span> ✧</span></strong><span>我的星点</span></button><button class="btn line" data-page="report">每日复盘 ${icon('arrow')}</button></div><div class="columns"><div class="card today-tasks"><div class="card-head"><h2>今日题单</h2><span class="subtle">${p.budget} 分钟</span></div>${p.tasks.map(t=>taskHTML(t)).join('')||'<div class="empty">本轮备考已结束，题库和记录仍可回顾。</div>'}<details class="quiet-details"><summary>今天为什么这样安排</summary><p>${esc(p.reason)}</p></details></div><div class="right-col">${timerCard()}<div class="card recall-card"><span class="tag">先回忆，再求助</span><h3>会做一道，<br>再换一道验证。</h3><button class="btn soft" data-page="review">迁移复习 ${dueQuestions().length?`· ${dueQuestions().length}`:''} ${icon('arrow')}</button></div><details class="card goal-details"><summary>630 分目标分配</summary>${Object.keys(SUBJECTS).map(k=>`<div class="score-row"><div class="row between"><span>${SUBJECTS[k]}</span><span>${PROFILE.scores[k]} → ${PROFILE.targets[k]}</span></div><div class="progress"><i style="width:${PROFILE.scores[k]/PROFILE.targets[k]*100}%"></i></div></div>`).join('')}<p class="small muted">目标分配，不是预测成绩。</p></details></div></div>`;}
function planView(){return header('把 630 分，拆成每天的一小步。','10 月 6 日起 · 每天最多 4 小时 · 每周减量 · 考前收尾')+`<div class="card"><div class="card-head"><h2>备考路线</h2><span class="chip">2026.10 → 11</span></div><div class="row small muted"><span>06 诊断</span><span>→ 07–17 补弱</span><span>→ 18–28 限时题组</span><span>→ 29–04 稳定</span><span>→ 05–07 收尾</span></div><div class="calendar">${Array.from({length:33},(_,i)=>add(PROFILE.startDate,i)).map((d,i)=>`<button class="day ${d===selectedDate?'selected':''} ${d===state.today?'is-today':''}" data-date="${d}"><b>${d.slice(5).replace('-','/')}</b><small>${d===state.today?'今天':d>='2026-11-05'?'轻量收尾':i%7===6?'减量恢复':'稳步前进'}</small></button>`).join('')}</div><div id="plan-detail"></div></div><div class="card" style="margin-top:20px"><h3>计划怎样调整</h3><p class="small muted" style="margin:10px 0">每天提交复盘后，本地规则依据疲劳、完成率和足量作答数据调整明天。不会自动联系本聊天；你可以复制汇报发给我，再导入我给出的计划。已完成记录保留。</p><div class="row"><button class="btn soft" data-page="report">复盘与优化</button><button class="btn line" id="coach-open">导入教练计划</button></div></div>`;}
function practiceView(){let pool=bank.filter(q=>(filter==='all'||q.subject===filter)&&(query===''||[q.title,q.prompt,q.source,TOPICS[q.topic]].join(' ').toLowerCase().includes(query.toLowerCase())));return header('每天做具体的题，不必翻整套卷子。',`已整理 ${bank.filter(q=>q.official).length} 项官方题目／题组，另有 ${bank.filter(q=>!q.official).length} 道原创基础练习。`)+`<div class="tabs">${[['all','全部'],...Object.entries(SUBJECTS)].map(([k,v])=>`<button data-filter="${k}" class="${filter===k?'active':''}">${v}</button>`).join('')}</div><div class="card"><div class="toolbar"><input id="search" class="text search" aria-label="搜索知识点或题号" placeholder="搜索：波 / 电容 / 积分 / 2021…" value="${esc(query)}"><button class="btn soft" id="start-filter">练当前筛选的前 5 题</button></div><p class="small muted">官方题保留原图表；长题先在纸上演算，再在这里提交。原创题用于补基础，不代表正式考试难度。</p><div id="question-list">${pool.slice(0,80).map(q=>questionRow(q)).join('')||'<div class="empty">没有匹配的题目，换个关键词试试。</div>'}</div>${pool.length>80?'<p class="small muted">展示前80项，使用科目或关键词缩小范围。</p>':''}</div>`;}
function questionRow(q){return `<div class="question-card"><div><div class="row"><span class="tag">${SUBJECTS[q.subject]}</span><span class="tag">${TOPICS[q.topic]||q.topic}</span><span class="tag">${q.official?'官方过去问':'原创基础'}</span></div><h3 style="margin-top:7px">${esc(q.title||q.prompt)}</h3><p>${esc(q.official?q.source:'每题含讲解')} · 约 ${q.minutes} 分钟${state.mastery[q.id]?' · 已练习':''}</p></div><button class="btn soft small" data-question="${q.id}">做这题</button></div>`;}
function reviewView(){const wrong=bank.filter(q=>state.mastery[q.id]?.wrong||state.attempts.some(a=>a.questionId===q.id&&a.hinted)),queue=state.reviewQueue||[],due=queue.filter(r=>r.questionId);return header('换一道题，看看真的会了吗。','同考点 · 不同条件 · 无提示验证',`<button id="review-start" class="btn" ${due.length?'':'disabled'}>开始迁移复习 · ${due.length}</button>`)+`<div class="card"><h2>到期考点</h2>${queue.length?queue.map(r=>{const original=qby(r.originalId),next=qby(r.questionId);return `<div class="list-item"><h3>${esc(original.title||original.prompt)}</h3><p>${next?`${r.kind==='recall'?'词汇回忆':'新题验证'}：${esc(next.title||next.prompt)}`:'当前没有未做过的同考点题，已标记待补题。可在日报中请求教练补充。'}</p>${next?`<button class="btn soft small" data-transfer="${next.id}" data-original="${original.id}" style="margin-top:10px">${r.kind==='recall'?'回忆词汇':'做这道新题'}</button>`:''}</div>`;}).join(''):'<div class="empty">今天没有到期考点。看过提示或做错的题，会在次日安排迁移验证。</div>'}</div><details class="card" style="margin-top:20px" open><summary>薄弱点记录 · ${wrong.length}</summary>${wrong.map(q=>`<div class="list-item">${questionRow(q)}<p>下次验证 ${state.mastery[q.id].due} · 独立迁移 ${state.mastery[q.id].transferStreak||0} 次</p></div>`).join('')||'<p class="small muted">完成练习后自动记录。</p>'}</details>`;}
function guidesView(){return header('卡住的时候，先把关键一步弄明白。','短讲解、典型例子与常见陷阱。看完立即做题验证。')+`<div class="grid3">${GUIDES.map(g=>`<div class="card lesson"><span class="tag">${SUBJECTS[g.subject]||'学习方法'}</span><h3>${g.title}</h3><p>${g.summary}</p><button class="btn soft small" data-guide="${g.id}">打开讲解 ${icon('arrow')}</button></div>`).join('')}</div>`;}
function reportView(){const r=state.reports[state.today],latest=state.adjustments.findLast(a=>a.id==='adjust-'+state.today&&!a.reverted);return header('用今天的结果，让明天更合适。','真实记录比漂亮数字更重要。不会因为没完成而加倍补任务。')+`<div class="grid2"><div class="card"><div class="card-head"><h2>每日复盘</h2><span class="chip">${state.today}</span></div><form id="report-form"><div class="field"><label for="fatigue">现在的疲劳程度</label><select id="fatigue">${[1,2,3,4,5].map((n,i)=>`<option value="${n}" ${r?.fatigue===n||!r&&n===3?'selected':''}>${n} · ${['很轻松','状态不错','正常','比较疲惫','需要休息'][i]}</option>`).join('')}</select></div><div class="field"><label for="available">明天能安排多少分钟（60–240）</label><input id="available" type="number" min="60" max="240" value="${r?.available||240}" required></div><div class="field"><label for="reflection">今天哪里有进步，哪里卡住了？</label><textarea id="reflection" placeholder="例如：波形方向已经能判断，但电容断开电源后还是容易混淆。今天上课较累。">${esc(r?.note||'')}</textarea></div><button class="btn" type="submit">保存复盘并优化明天 ${icon('arrow')}</button></form><p class="small muted" style="margin-top:15px">保存先生成本地建议。需要进一步分析时，点击右侧 Codex 教练。</p>${latest?`<div class="divider"></div><h3>明日调整依据</h3><p class="note" style="margin:10px 0">${esc(latest.reason)}</p><div class="row">${Object.entries(latest.allocations).map(([k,v])=>`<span class="tag">${SUBJECTS[k]} ${v} 分钟</span>`).join('')}</div><button class="linkbutton" id="undo-adjust" style="margin-top:10px">撤销这次本地调整</button>`:''}</div><div class="card"><div class="card-head"><h2>发给我的每日汇报</h2><button class="btn soft small" id="copy-report">复制汇报</button></div><textarea id="report-output" class="report-text" readonly aria-label="每日学习汇报">${esc(reportText||'正在整理学习记录…')}</textarea><div class="row" style="margin-top:15px"><button class="btn" id="ai-plan-open">请 Codex 分析并调整</button><button class="btn soft" id="download-report">下载汇报</button><button class="btn line" id="coach-open">导入教练计划</button></div><p class="small muted" style="margin-top:13px">可在软件内调用 Codex，也可复制汇报继续在本聊天讨论。Codex 使用现有登录与额度，只在点击时发送本次学习资料。</p></div></div><div class="card" style="margin-top:20px"><h2>最近的记录</h2>${Object.values(state.reports).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,7).map(x=>`<div class="list-item"><div class="row between"><h3>${x.date}</h3><span class="tag">${x.minutes} 分钟 · 疲劳 ${x.fatigue}/5</span></div><p>${esc(x.note||'未填写文字')}</p><button class="linkbutton" data-oldreport="${x.date}">查看这一天的汇报</button></div>`).join('')||'<p class="small muted" style="margin-top:15px">完成第一次复盘后，这里会保留你的成长记录。</p>'}</div>`;}
function rewardsView(){const earned=sum(Object.values(state.earned)),level=Math.floor(earned/100)+1;return header('努力，会留下看得见的痕迹。','星点可兑换休息奖励与界面主题。')+`<div class="garden-banner"><div><span class="hero-date">我的成长花园 · Lv.${level}</span><h2>${state.points} <span>可用星点</span></h2><div class="progress"><i style="width:${earned%100}%"></i></div></div><span class="garden-tree">${level<3?'♧':'❋'}</span></div><h2 class="section-title">成就收藏</h2><div class="grid3 achievement-grid">${(state.achievements||[]).map(a=>`<div class="achievement ${a.unlocked?'unlocked':''}"><span class="badge-glyph">${a.glyph}</span><div><h3>${esc(a.name)} ${a.unlocked?'✓':''}</h3><p>${esc(a.desc)}</p><div class="progress"><i style="width:${Math.min(100,a.value/a.target*100)}%"></i></div><span class="small muted">${Math.min(a.value,a.target)} / ${a.target} · ${a.unlocked?'已获':'解锁获'} ${a.bonus} 星点</span></div></div>`).join('')}</div><h2 class="section-title">给自己的奖励</h2><div class="grid3">${Object.entries(state.rewardCatalog||{}).map(([id,r])=>{const unlocked=r.unlock&&state.redemptions.some(x=>x.unlock===r.unlock);return `<div class="card reward"><div class="reward-art">${icon(r.icon)}</div><h3>${esc(r.name)}</h3><p>${r.unlock?'兑换后可随时切换':'兑换后为自己安排这份奖励'}</p>${unlocked?`<button class="btn soft" data-theme="${r.unlock}">使用主题</button>`:`<button class="btn ${state.points<r.cost?'line':''}" data-redeem="${id}" ${state.points<r.cost?'disabled':''}>${r.cost} 星点兑换</button>`}</div>`;}).join('')}</div><div class="row" style="margin-top:18px"><button class="btn line small" data-theme="sage">恢复原野主题</button></div><details class="card" style="margin-top:20px"><summary>星点规则</summary><p class="small muted" style="margin-top:12px">完成任务 +10，首次尝试一道新题 +2，原错题首次独立答对 +3，首次闭卷复述 +2，每日复盘 +15，完成一段至少15分钟专注 +5。成就奖励只发一次；主题只能兑换一次。休息不扣分，日常休息无需先赚星点。</p></details><div class="card"><h3>已兑换的奖励</h3>${state.redemptions.slice().reverse().map(r=>`<div class="list-item row between"><span>${esc(r.name)}</span><span class="small muted">${r.date} · ${r.cost} 星点</span></div>`).join('')||'<div class="empty">为下一份小奖励积累星点。</div>'}</div>`;}
function settingsView(){return header('你的资料，有来源；你的记录，有备份。','核心学习功能与已下载的音频、题页都可在本机离线使用。')+`<div class="grid2"><div class="card"><h2>学习记录与备份</h2><p class="small muted" style="margin:12px 0 20px">记录写入本机项目 data/state.json，每次修改保留历史快照。换浏览器不会丢失。导出备份可以交给我恢复或分析。</p><a href="/api/export" class="btn" download>下载学习记录备份</a><div class="divider"></div><h3>录入已取得的成绩</h3><p class="small muted" style="margin:8px 0">这里只记录官方成绩或机构模考分，不把自测正确率换算成EJU分数。</p><form id="score-form"><div class="grid2">${Object.keys(SUBJECTS).map(k=>`<div class="field"><label>${SUBJECTS[k]}</label><input name="${k}" type="number" min="0" max="${k==='japanese'?400:k==='math'?200:100}" required aria-label="${SUBJECTS[k]}成绩"></div>`).join('')}</div><div class="field"><label>成绩来源</label><select name="source"><option>官方成绩</option><option>机构模考</option></select></div><button class="btn soft">保存成绩</button></form>${state.scores.map(s=>`<p class="small muted" style="margin-top:10px">${s.date} · ${s.source} · ${sum(Object.values(s.scores))} 分</p>`).join('')}</div><div class="card"><h2>公开资料与使用说明</h2><p class="small muted" style="margin:12px 0">真题来自 JASSO 官方网站，原始 PDF 与音频保存在本机，仅供个人学习。软件按题号展示原页；不使用文字识别结果替代原题。日语公开题存在授权缺页；旧题不等于2026完整考纲。</p><div class="list-item"><a href="https://www.jasso.go.jp/ryugaku/eju/examinee/pastpaper_sample/index.html" target="_blank" rel="noreferrer">JASSO 公开过去问</a></div><div class="list-item"><a href="https://www.jasso.go.jp/en/ryugaku/eju/examinee/syllabus/index.html" target="_blank" rel="noreferrer">2026 年官方考纲</a></div><div class="list-item"><h3>日语听力</h3><p>官方题使用 JASSO 真人音频；标注“原创”的短题使用 Kyoko 日语合成语音。两者分别标识。</p></div><div class="list-item"><h3>音乐</h3><p>Meditation Impromptu 01 / 02 / 03 — Kevin MacLeod (incompetech.com)。原音频未改动。</p><a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a> · <a href="https://incompetech.com/music/royalty-free/index.html?Search=Search&isrc=USUAN1100161" target="_blank" rel="noreferrer">作者与来源</a></div><div class="list-item"><h3>灰原哀动态壁纸</h3><p>来自 DesktopHut 的公开 MP4，仅用于这台电脑的个人学习界面；未核实原画作者，保留原画署名。不代表获得商业再分发授权。</p><a href="https://www.desktophut.com/Detective-Conan-Ai-Haibara-Anime-Live-Wallpaper" target="_blank" rel="noreferrer">壁纸来源</a></div><div class="list-item"><h3>计划调整边界</h3><p>本地规则可减量和调整专题。点击 Codex 教练时，会联网分析题目或日报，使用当前 Codex 登录与额度；计划先预览后应用。没有自动评分或提分保证。</p></div><button class="btn line" id="coach-open" style="margin-top:15px">导入教练给的新计划</button><div class="divider"></div><h3>Codex 连接</h3><p class="small muted">使用本机 Codex CLI 的 ChatGPT 登录。网络请求会发送当前题目、你的尝试或日报摘要，不会自动读取本聊天。失败时可继续使用离线学习功能。</p><button class="btn soft small" id="ai-status" style="margin-top:10px">检查连接</button><div id="ai-status-result"></div></div></div>`;}
function render(){if(!state)return;$('#app').innerHTML=shell();$('#view').innerHTML=({today:todayView,plan:planView,practice:practiceView,review:reviewView,guides:guidesView,report:reportView,rewards:rewardsView,settings:settingsView}[page])();bind();updateTimerUI();syncWallpaper();if(page==='plan')loadPlan(selectedDate||state.today);if(page==='report')loadReport();}
function bind(){on('#ai-plan-open','click',aiPlanDialog);on('#ai-status','click',async()=>{const x=await request('/api/ai/status');$('#ai-status-result').textContent=x.available?(x.busy?'Codex 正在处理请求。':'已找到 Codex CLI。登录和网络将在实际请求时验证。'):'未找到 Codex CLI。';});for(const b of $$('button[data-theme]'))b.onclick=()=>{const value=b.dataset.theme;localStorage.setItem('eju-theme',value);document.documentElement.dataset.theme=value;toast('主题已切换。');};for(const b of $$('[data-transfer]'))b.onclick=()=>startSession([b.dataset.transfer],null,{[b.dataset.transfer]:b.dataset.original});on('#wallpaper-mode','change',e=>{localStorage.setItem('eju-wallpaper',e.target.value);render();});for(const b of $$('[data-page]'))b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0);};for(const b of $$('[data-study]'))b.onclick=safely(()=>studyTask(b.dataset.study));for(const b of $$('[data-complete]'))b.onclick=()=>completeDialog(b.dataset.complete);for(const b of $$('[data-question]'))b.onclick=()=>startSession([b.dataset.question]);for(const b of $$('[data-guide]'))b.onclick=()=>guideDialog(b.dataset.guide);for(const b of $$('[data-filter]'))b.onclick=()=>{filter=b.dataset.filter;render();};for(const b of $$('[data-date]'))b.onclick=()=>{selectedDate=b.dataset.date;render();};for(const b of $$('[data-redeem]'))b.onclick=()=>rewardDialog(b.dataset.redeem);for(const b of $$('[data-oldreport]'))b.onclick=safely(async()=>{const r=await request('/api/report?date='+b.dataset.oldreport);openModal('历史汇报',`<textarea class="report-text" readonly>${esc(r.text)}</textarea>`);});
 on('#continue','click',()=>session?quizDialog():studyTask(plan().tasks.find(t=>!state.records[t.id]?.completed)?.id||plan().tasks[0]?.id));on('#music-toggle','click',toggleMusic);on('#music-track','change',async e=>{track=e.target.value;localStorage.setItem('eju-track',track);const was=musicPlaying;bgm.src=assets.find(a=>a.id===track).path;if(was)await bgm.play();});on('#volume','input',e=>{localStorage.setItem('eju-volume',e.target.value);bgm.volume=ducks.size?0:Number(e.target.value);});on('#music-credit','click',()=>openModal('背景音乐来源',`<p>Meditation Impromptu 01、02、03</p><p>Kevin MacLeod (incompetech.com)</p><p class="small muted" style="margin:12px 0">原音频未改动。根据 CC BY 4.0 署名授权使用，已下载到本机。是否播放由你决定；做听力时自动静音。</p><div class="row"><a href="https://incompetech.com/music/royalty-free/index.html?Search=Search&isrc=USUAN1100161" target="_blank" rel="noreferrer">作者来源</a><a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">授权条款</a></div>`));
 on('#timer-toggle','click',toggleTimer);on('#timer-reset','click',()=>act({type:'timer',timer:null}));on('#timer-duration','change',()=>{if(!state.timer)updateTimerUI();});on('#review-start','click',()=>startSession(dueQuestions().slice(0,10).map(q=>q.id),null,Object.fromEntries((state.reviewQueue||[]).filter(r=>r.questionId).map(r=>[r.questionId,r.originalId]))));on('#search','input',e=>{query=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);});on('#start-filter','click',()=>startSession(bank.filter(q=>(filter==='all'||q.subject===filter)&&(!query||[q.title,q.prompt,q.source,TOPICS[q.topic]].join(' ').includes(query))).slice(0,5).map(q=>q.id)));
 on('#report-form','submit',async e=>{e.preventDefault();await act({type:'report',fatigue:Number($('#fatigue').value),available:Number($('#available').value),note:$('#reflection').value});toast('复盘已保存，明天的安排已更新。');});on('#copy-report','click',async()=>{await navigator.clipboard.writeText($('#report-output').value);toast('汇报已复制，粘贴到本聊天即可。');});on('#download-report','click',()=>download('EJU每日汇报-'+state.today+'.txt',$('#report-output').value));on('#undo-adjust','click',()=>act({type:'revertAdjustment',id:'adjust-'+state.today}));on('#coach-open','click',coachDialog);on('#score-form','submit',async e=>{e.preventDefault();const f=new FormData(e.target);await act({type:'score',source:f.get('source'),scores:Object.fromEntries(Object.keys(SUBJECTS).map(k=>[k,Number(f.get(k))]))});toast('成绩已保存。');});}
async function loadPlan(date){const p=await request('/api/plan?date='+date);if(page!=='plan')return;$('#plan-detail').innerHTML=`<div class="card-head"><h3>${date} · ${esc(p.stage)}</h3><span class="chip">${p.budget} 分钟</span></div><div class="note">${esc(p.reason)}</div>${p.tasks.map(t=>taskHTML(t,false)).join('')}<p class="small muted" style="margin-top:15px">未来题单会根据复盘调整；当天开始后题单固定，避免做到一半换题。</p>`;}
async function loadReport(){const r=await request('/api/report');reportText=r.text;if($('#report-output'))$('#report-output').value=reportText;}
function download(name,text){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openModal(title,body,wide=false){document.querySelectorAll('#modal-root audio').forEach(a=>a.pause());ducks.clear();restoreVolume();lastFocused=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="close" id="close-modal" aria-label="关闭">×</button></div>${body}</section></div>`;syncWallpaper();$('#close-modal').onclick=closeModal;$('#close-modal').focus();$('.modal-overlay').onclick=e=>{if(e.target.classList.contains('modal-overlay'))closeModal();};}
function closeModal(){document.querySelectorAll('#modal-root audio').forEach(a=>a.pause());ducks.clear();restoreVolume();$('#modal-root').innerHTML='';syncWallpaper();lastFocused?.isConnected&&lastFocused.focus();}
document.addEventListener('keydown',e=>{if(!$('.modal'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const nodes=$$('.modal button,.modal a,.modal input,.modal select,.modal textarea,.modal audio').filter(e=>!e.disabled&&e.offsetParent!==null),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
function guideDialog(id){const g=GUIDES.find(x=>x.id===id)||GUIDES.find(x=>x.id==='review');openModal(g.title,`<p class="muted">${g.summary}</p><ol class="lesson-steps">${g.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="formula">${esc(g.example)}</div><div class="note warm">常见陷阱：${esc(g.trap)}</div><button class="btn" id="guide-practice" style="margin-top:20px">做题验证 ${icon('arrow')}</button>`);on('#guide-practice','click',()=>startSession(bank.filter(q=>q.topic===id).slice(0,4).map(q=>q.id)));}
async function studyTask(id){const t=plan().tasks.find(t=>t.id===id);if(!t)return;await act({type:'timer',timer:{label:t.title,total:t.minutes*60,remaining:t.minutes*60,running:true}});if(t.topic==='writing')return writingDialog(t);startSession(t.questionIds,t.id,t.reviewLinks||{});}
function completeDialog(id){const t=plan().tasks.find(t=>t.id===id),r=state.records[id];if(!t)return;openModal('记录成果 · '+t.title,`<form id="complete-form"><p class="small muted" style="margin-bottom:18px">包含纸上演算、背诵和订正。填写真实成果；部分完成也值得记录。</p><div class="field"><label for="actual-minutes">实际学习分钟</label><input id="actual-minutes" type="number" min="1" max="240" value="${r?.minutes||t.minutes}" required></div><div class="field"><label for="task-note">完成了什么？还有哪里不会？</label><textarea id="task-note" required minlength="2" placeholder="例如：做了波形图3题，2题正确；传播方向还要再练。">${esc(r?.note||'')}</textarea></div><div class="field"><label for="task-status">完成状态</label><select id="task-status"><option value="yes" ${r?.completed?'selected':''}>本项任务已完成</option><option value="partial" ${r&&!r.completed?'selected':''}>部分完成，明天合理调整</option></select></div><button class="btn">保存成果</button></form>`);on('#complete-form','submit',async e=>{e.preventDefault();await act({type:'completeTask',taskId:id,minutes:Number($('#actual-minutes').value),note:$('#task-note').value,completed:$('#task-status').value==='yes'});closeModal();toast('学习成果已保存。');});}
function saveSession(){localStorage.setItem('eju-active-session',JSON.stringify(session));}
function startSession(ids,taskId=null,reviewLinks={}){if(!ids.length){toast('这个专题暂时没有可做题目，可先查看知识讲解。');return;}session={ids,index:0,taskId,reviewLinks,responses:{},attempts:{},selections:{},text:{},revealed:{},elapsed:{},hints:{},helpDraft:{},startedAt:Date.now()};saveSession();quizDialog();}
function optionsOrder(q){return q.official?q.options.map((_,i)=>i):q.options.map((_,i)=>i).sort((a,b)=>((a*17+q.id.charCodeAt(q.id.length-1))%7)-((b*17+q.id.charCodeAt(q.id.length-1))%7));}
function quizDialog(){if(!session)return;const q=qby(session.ids[session.index]);if(!q){session=null;localStorage.removeItem('eju-active-session');return;}const response=session.responses[q.id],answered=!!response,reveal=answered||session.revealed[q.id];const guide=GUIDES.find(g=>g.id===q.topic);openModal(q.title||`${SUBJECTS[q.subject]} · ${TOPICS[q.topic]||'练习'}`,`<div class="qnav">${session.ids.map((id,i)=>`<button data-qindex="${i}" class="${i===session.index?'active':''} ${session.responses[id]?'answered':''}" aria-label="第${i+1}题">${i+1}</button>`).join('')}</div><div class="row"><span class="tag">${q.official?'JASSO 官方过去问':'原创专项练习'}</span><span class="tag">${TOPICS[q.topic]||q.topic}</span><span class="tag">试行限时 ${q.minutes} 分钟</span><span class="tag" id="qelapsed">已用 0:00</span></div><div class="question-layout"><div>${session.reviewLinks?.[q.id]?`<div class="transfer-note">本题用于验证：${esc(qby(session.reviewLinks[q.id])?.title||qby(session.reviewLinks[q.id])?.prompt)}。请独立作答。</div>`:''}<p class="question-title">${esc(q.prompt)}</p>${q.audio?`<p class="small muted">${q.official?'官方真人录音，选项以音频为准。':'日语合成语音 · 用于短句专项，不代替官方听力。'}</p><audio class="audio-player" id="question-audio" controls preload="metadata" src="${esc(q.audio)}"></audio><div class="row"><label class="small muted" for="audio-rate">复听速度</label><select id="audio-rate" class="text" style="width:100px"><option value="1">1.0 ×</option><option value="0.85">0.85 ×</option><option value="1.1">1.1 ×</option></select><span class="tiny muted">首听建议 1.0 ×</span></div>`:''}${(q.images||[]).map(src=>`<a href="${src}" target="_blank" rel="noreferrer" title="打开大图"><img class="question-img" src="${src}" alt="${esc(q.title)} 原题页，点击放大"></a>`).join('')}${q.official?`<div class="paper-credit">${esc(q.source)} · 原题原图。<a href="${q.pdf}#page=${q.page}" target="_blank" rel="noreferrer">查看来源原页</a></div>`:''}${q.selfGrade?`<div class="field"><label for="written-response">先写答案／关键步骤（也可先写在纸上，在此录入结论）</label><textarea id="written-response" ${answered?'readonly':''} placeholder="记录填空结果和思路，再核对官方答案。">${esc(session.text[q.id]||'')}</textarea></div>${!reveal?'<button class="btn soft" id="reveal-answer">已独立作答，核对官方答案</button>':''}`:`<div class="options">${optionsOrder(q).map((i,n)=>`<button class="option ${session.selections[q.id]===i?'selected':''} ${answered&&q.answer===i?'correct':''} ${answered&&response.answer===i&&!response.correct?'incorrect':''}" data-option="${i}" ${answered?'disabled':''}><b>${q.official?i+1:String.fromCharCode(65+n)}</b><span>${esc(q.options[i])}</span></button>`).join('')}</div>`}${reveal?`<div class="explanation"><strong>${answered?(response.correct?(response.overtime?'✓ 做对了，但超过试行限时':response.hinted?'✓ 提示后做对':'✓ 独立做对'):'再看一遍关键步骤'):'核对官方答案'}</strong>${esc(q.explanation||'请对照下方官方答案，并记录卡住的步骤。')}</div>${q.answerImages?.map(src=>`<img class="question-img" src="${src}" alt="官方答案页">`).join('')||''}${q.transcript?`<details open><summary>听力原文</summary><p style="white-space:pre-wrap;margin-top:12px">${esc(q.transcript)}</p></details>`:''}${q.transcriptImages?.length?`<details open><summary>官方听力原文（只复盘本题）</summary>${q.transcriptImages.map(src=>`<img class="question-img" src="${src}" alt="听力官方原文">`).join('')}</details>`:''}`:''}</div><aside><div class="note">${q.selfGrade?'长题按完整题组安排。核对官方答案后自评；自评分与自动判题会分开标记。':'先独立作答。卡住时先尝试提示；看懂之后再闭卷复述。'}</div>${guide?`<div class="guide-links"><button id="quiz-guide">${icon('book')} 知识点：${guide.title.split('：')[0]}</button></div>`:''}${!answered?`<label class="small muted" style="display:block;margin-top:15px"><input type="checkbox" id="used-help" ${session.hints?.[q.id]?'checked':''}> 这题借助过 AI 或讲解</label>`:''}<div class="field" style="margin-top:16px"><label for="error-kind">主要瓶颈（做对但慢也请选）</label><select id="error-kind" ${answered?'disabled':''}>${['无','记忆','引导衔接','读题','计算','时间','知识','听音','逻辑'].map(k=>`<option ${response?.error===k?'selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label for="question-note">一句话记录疑问（可选）</label><textarea id="question-note" ${answered?'readonly':''} placeholder="哪一步不明白？汇报时会一起带上。">${esc(response?.note||'')}</textarea></div>${!answered?(q.selfGrade?(reveal?'<div class="row"><button class="btn" id="grade-right">核对后：做对了</button><button class="btn line" id="grade-wrong">还有错误</button></div>':''):'<button class="btn" id="submit-answer">提交答案</button>'):`<div class="note ${response.correct?'':'warm'}">${response.correct?(response.hinted?'提示后做对：明天优先换同考点新题，暂不计为独立掌握。':'已保存本次独立作答。'):'已记录薄弱点，明天优先用不同题目验证。'}</div>`}${!answered?'<div class="divider"></div><button class="btn line" id="help-open">卡住了 · 先给我提示</button><div id="help-area"></div>':'<div class="divider"></div><button class="btn soft" id="recall-open">遮住解析，自己复述</button><div id="recall-area"></div>'}<div class="divider"></div><div class="row"><button class="btn line small" id="qprev" ${session.index===0?'disabled':''}>上一题</button><button class="btn soft small" id="qnext">${session.index===session.ids.length-1?'完成这组':'下一题'} ${icon('arrow')}</button></div><p class="small muted" style="margin-top:15px">当前进度自动保存。关闭窗口后，可从首页继续。</p></aside></div>`,true);
for(const b of $$('[data-qindex]'))b.onclick=()=>{saveInput();session.index=Number(b.dataset.qindex);saveSession();quizDialog();};for(const b of $$('[data-option]'))b.onclick=()=>{session.selections[q.id]=Number(b.dataset.option);saveSession();$$('[data-option]').forEach(x=>x.classList.toggle('selected',x===b));};on('#written-response','input',e=>{session.text[q.id]=e.target.value;saveSession();});on('#reveal-answer','click',()=>{saveInput();if(!session.text[q.id]?.trim())throw Error('先写下你的答案或关键步骤。');session.revealed[q.id]=true;saveSession();quizDialog();});on('#submit-answer','click',()=>submit(q));on('#grade-right','click',()=>submit(q,true));on('#grade-wrong','click',()=>submit(q,false));on('#qprev','click',()=>{saveInput();session.index--;saveSession();quizDialog();});on('#qnext','click',()=>{saveInput();if(session.index<session.ids.length-1){session.index++;saveSession();quizDialog();}else finishSession();});on('#quiz-guide','click',()=>{saveInput();session.hints ||= {};session.hints[q.id]=true;saveSession();const g=guide;const d=document.createElement('details');d.open=true;d.innerHTML=`<summary>${esc(g.title)}</summary><ol>${g.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>`;$('#quiz-guide').parentElement.after(d);$('#quiz-guide').disabled=true;});on('#help-open','click',()=>helpLadder(q));on('#recall-open','click',()=>recallPanel(q));on('#audio-rate','change',e=>{$('#question-audio').playbackRate=Number(e.target.value);});wireAudio();}
function saveInput(){if(session&&$('#written-response')){session.text[session.ids[session.index]]=$('#written-response').value;saveSession();}}
async function submit(q,selfCorrect){const button=$('#submit-answer')||$('#grade-right');if(button?.disabled)return;if(button)button.disabled=true;try{saveInput();const selection=session.selections[q.id];if(!q.selfGrade&&!Number.isInteger(selection))throw Error('请先选择答案。');const id=session.attempts[q.id]||crypto.randomUUID();session.attempts[q.id]=id;saveSession();const a={type:'answer',attemptId:id,questionId:q.id,reviewOf:session.reviewLinks?.[q.id]||null,answer:selection,seconds:session.elapsed?.[q.id]||0,hinted:!!session.hints?.[q.id]||!!$('#used-help')?.checked,response:session.text[q.id]||'',correct:selfCorrect,error:$('#error-kind').value,note:$('#question-note').value};await act(a);session.responses[q.id]=state.attempts.find(x=>x.id===id);saveSession();quizDialog();}finally{if(button?.isConnected)button.disabled=false;}}
function finishSession(){const done=Object.keys(session.responses).length,correct=Object.values(session.responses).filter(r=>r.correct).length,taskId=session.taskId;openModal('这组练习，辛苦了。',`<div class="stats" style="grid-template-columns:1fr 1fr"><div class="stat"><div class="stat-top">已提交</div><div class="num">${done}<span>/ ${session.ids.length} 题</span></div></div><div class="stat"><div class="stat-top">正确</div><div class="num">${correct}<span>题</span></div></div></div><p class="note">${done<session.ids.length?'还有未提交的题，可以继续，也可以先记录部分成果。':'错题已安排后续复习。请把纸上演算、讲解与订正时间一并计入实际学习成果。'}</p><div class="row" style="margin-top:20px"><button class="btn soft" id="return-quiz">返回题组</button>${taskId?'<button class="btn" id="finish-record">记录这项任务</button>':'<button class="btn" id="finish-close">结束练习</button>'}</div>`);on('#return-quiz','click',quizDialog);on('#finish-record','click',()=>{session=null;localStorage.removeItem('eju-active-session');completeDialog(taskId);});on('#finish-close','click',()=>{session=null;localStorage.removeItem('eju-active-session');closeModal();render();});}
function writingDialog(t){const key='writing-'+state.today,prompt=WRITING[Math.floor(Date.parse(state.today)/86400000)%WRITING.length];openModal('记述 · 先表达清楚，再修改',`<p class="question-title">${prompt}</p><div class="note">建议 400–500 日文字符，30分钟内完成；这里只做练习自查，不自动评分。</div><div class="field" style="margin-top:15px"><textarea id="writing-text" style="min-height:300px" placeholder="ここに書いてください…">${esc(state.drafts[key]||'')}</textarea><span class="writing-count" id="writing-count"></span></div><div class="row"><button class="btn" id="writing-save">保存原文</button><button class="btn soft" id="writing-record">保存并记录成果</button></div><p class="small muted" style="margin-top:15px">自查：立场明确？理由支持结论？有具体例子？回应了问题？作文原文会包含在每日汇报里。</p>`,true);const count=()=>$('#writing-count').textContent=$('#writing-text').value.replace(/\s/g,'').length+' 字符';count();on('#writing-text','input',count);on('#writing-save','click',async()=>{await act({type:'draft',key,text:$('#writing-text').value});toast('作文原文已保存。');});on('#writing-record','click',async()=>{await act({type:'draft',key,text:$('#writing-text').value});completeDialog(t.id);});}
function coachDialog(){pendingCoach=null;openModal('导入教练调整',`<p class="small muted">把我根据你的汇报给出的 JSON 粘贴到这里。先预览，再应用；不会删除已有学习记录。每日总时长仍限制在4小时以内。</p><div class="field" style="margin-top:15px"><label for="coach-json">计划 JSON</label><textarea id="coach-json" style="min-height:190px" placeholder='{"fromDate":"${add(state.today,1)}","toDate":"${add(state.today,3)}","allocations":{"japanese":80,"math":65,"physics":55,"chemistry":40},"focus":{"physics":"wave"},"note":"调整原因"}'></textarea></div><button class="btn soft" id="coach-preview">预览调整</button><div id="coach-result"></div>`);on('#coach-preview','click',async()=>{const text=$('#coach-json').value.replace(/^```(?:json)?\s*|\s*```$/g,'');const p=JSON.parse(text);const r=await request('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'previewCoach',plan:p})});pendingCoach=r.plan;$('#coach-result').innerHTML=`<div class="note" style="margin:15px 0"><b>${esc(p.fromDate)} 至 ${esc(p.toDate)}</b><br>${Object.entries(p.allocations).map(([k,v])=>`${SUBJECTS[k]} ${v} 分钟`).join(' · ')}<br>${esc(p.note)}</div><button id="coach-apply" class="btn">应用这份计划</button>`;on('#coach-apply','click',async()=>{await act({type:'coach',plan:pendingCoach});closeModal();toast('教练计划已应用，从指定日期开始。');});});}
function rewardDialog(id){const r=state.rewardCatalog[id];if(!r)return;openModal('兑换奖励',`<h3>${esc(r.name)}</h3><p class="note" style="margin:15px 0">使用 ${r.cost} 星点。${r.unlock?'主题会永久解锁。':'兑现一份给自己的小奖励。'}</p><button class="btn" id="redeem-confirm">确认兑换</button>`);on('#redeem-confirm','click',async()=>{await act({type:'redeem',reward:id,requestId:crypto.randomUUID()});if(r.unlock){localStorage.setItem('eju-theme',r.unlock);document.documentElement.dataset.theme=r.unlock;}closeModal();toast(r.unlock?'主题已解锁。':'奖励已兑换，好好享受这份休息。');});}
function remainingTimer(){if(!state?.timer)return Number($('#timer-duration')?.value||25)*60;const t=state.timer;return Math.max(0,t.running?Math.ceil((t.endsAt-Date.now())/1000):Math.ceil(t.remaining));}
let timerEnded=false;
function updateTimerUI(){if(!state)return;const t=state.timer,seconds=remainingTimer(),m=Math.floor(seconds/60),s=seconds%60;if($('#timer-clock'))$('#timer-clock').textContent=String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');if($('#timer-label'))$('#timer-label').textContent=t?.label||'一次只做一件事';if($('#timer-toggle'))$('#timer-toggle').textContent=t?.running?'暂停':t?'继续':'开始专注';if($('.timer-ring'))$('.timer-ring').style.setProperty('--progress',t?Math.min(100,(1-seconds/t.total)*100)+'%':'0%');if(t?.running&&seconds===0&&!timerEnded){timerEnded=true;act({type:'timerComplete'}).then(()=>{toast('这一段专注结束了，休息一下，再记录成果。');timerEnded=false;}).catch(()=>{timerEnded=false;});}}
async function toggleTimer(){let t=state.timer;if(!t||remainingTimer()===0){const total=Number($('#timer-duration')?.value||25)*60;t={total,remaining:total,label:total===300?'休息一下':'专注练习',running:true};}else t={...t,remaining:remainingTimer(),running:!t.running};await act({type:'timer',timer:t});}
setInterval(()=>{updateTimerUI();if(session&&$('#qelapsed')){const id=session.ids[session.index];session.elapsed ||= {};if(!document.hidden&&!session.responses[id]){session.elapsed[id]=(session.elapsed[id]||0)+1;saveSession();}const sec=Math.floor(session.elapsed[id]||0);$('#qelapsed').textContent=`已用 ${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;if(sec>qby(id).minutes*60)$('#qelapsed').style.color='#a27a48';}},1000);
async function toggleMusic(){if(musicPlaying){bgm.pause();musicPlaying=false;}else{const a=assets.find(a=>a.id===track&&a.available);if(!a)throw Error('音乐文件暂不可用');if(!bgm.src.endsWith(a.path))bgm.src=a.path;try{await bgm.play();musicPlaying=true;}catch(e){throw Error('浏览器未能播放音乐，请再点一次播放或保持安静。');}}render();}
function restoreVolume(){bgm.volume=ducks.size?0:Number(localStorage.getItem('eju-volume')??.22);if($('#music-status'))$('#music-status').textContent=ducks.size?'听力播放中，背景音乐已静音':'';}
function wireAudio(){const a=$('#question-audio');if(!a)return;a.addEventListener('play',()=>{ducks.add('question');restoreVolume();});for(const event of ['pause','ended','error'])a.addEventListener(event,()=>{ducks.delete('question');restoreVolume();if(event==='error')toast('音频加载失败，可打开资料来源或检查本机文件。');});}
window.addEventListener('error',e=>console.error(e.error));
try{[state,bank,assets]=await Promise.all([request('/api/state'),request('/api/questions'),request('/assets/manifest.json')]);selectedDate=state.today;try{session=JSON.parse(localStorage.getItem('eju-active-session'));if(session&&!session.ids?.every(id=>qby(id)))session=null;}catch{session=null;}render();}catch(e){$('#app').innerHTML=`<div class="boot"><h1>学习空间暂时没能打开</h1><p style="margin:20px">${esc(e.message)}</p><button class="btn" onclick="location.reload()">重新加载</button><p class="muted" style="margin-top:20px">请双击桌面的“澄学 EJU”启动器。已有记录不会被清空。</p></div>`;}

function helpLadder(q){
 $('#help-area').innerHTML=`<div class="note warm" style="margin-top:12px">先用约90秒尝试。如果你已在纸上做过，直接写出卡点，不必等计时。</div><div class="field" style="margin-top:12px"><label for="help-attempt">我知道什么？尝试了什么？具体卡在哪里？</label><textarea id="help-attempt" placeholder="已知…，要求…，我用了…，但…">${esc(session.helpDraft?.[q.id]||'')}</textarea></div><div class="row"><button class="btn soft small" id="hint-one">提示 1 · 看条件</button><button class="btn line small" id="hint-two" disabled>提示 2 · 找工具</button></div><div id="hint-text"></div><div class="divider"></div><button id="ai-hint" class="btn soft small" style="margin-top:8px">请 Codex 给下一步提示</button><div id="ai-hint-result"></div><button id="ask-ai-card" class="linkbutton" style="margin-top:12px">仍不会，生成只问下一步的提问卡</button>`;
 if(session.aiHints?.[q.id])$('#ai-hint-result').innerHTML=session.aiHints[q.id].map(x=>`<div class="note" style="margin-top:10px">${esc(x.hint)}<br>${esc(x.checkQuestion)}</div>`).join('');
 const capture=()=>{const t=$('#help-attempt').value.trim();if(t.length<8)throw Error('先简短写下自己的尝试与卡点（至少8个字）。');session.helpDraft ||= {};session.helpDraft[q.id]=t;session.hints ||= {};session.hints[q.id]=true;saveSession();return t;};
 on('#ai-hint','click',async()=>{const attempt=capture(),current=session;const previous=current.aiHints?.[q.id]||[];const result=await runCoach({type:'hint',questionId:q.id,attempt,level:Math.min(3,previous.length+1),previousHints:previous},'#ai-hint-result','#ai-hint');if(!result)return;current.aiHints ||= {};current.aiHints[q.id] ||= [];current.aiHints[q.id].push(result);if(session===current){saveSession();if($('#ai-hint-result'))$('#ai-hint-result').innerHTML=`<div class="note" style="margin-top:12px">${esc(result.observation)}<br><strong>${esc(result.hint)}</strong><br>${esc(result.checkQuestion)}</div>`;}});
 on('#hint-one','click',()=>{capture();$('#hint-text').innerHTML='<div class="note" style="margin-top:12px">只处理当前所求：圈出限制条件、单位、正负方向或否定词。数学先说出当前空格需要哪个中间量，听力先区分最初提案和最终决定。</div>';$('#hint-two').disabled=false;});
 on('#hint-two','click',()=>{capture();const g=GUIDES.find(g=>g.id===q.topic);$('#hint-text').innerHTML=`<div class="note" style="margin-top:12px">${esc(g?.steps[0]||'沿题目给出的变量与已知结论列出一条关系。先完成一个能确认的小步骤。')}<br>现在收起提示，自己向下写两步。</div>`;});
 on('#ask-ai-card','click',async()=>{const t=capture();const text=`我在准备EJU，有高考基础，主要是知识遗忘和题型不适应。\n题目：${q.title||q.prompt}\n编号：${q.id}\n来源：${q.sourceUrl||q.source}${q.page?'，PDF第'+q.page+'页':''}\n我的尝试和卡点：${t}\n请先检查我的思路，只给一个下一步提示，不要直接提供完整解答或最终答案。等我回复尝试后，再决定是否给下一层提示。最后请让我闭卷复述关键转折。`;await navigator.clipboard.writeText(text);toast('提问卡已复制。粘贴到本聊天；不会自动发送。');});
}
function recallPanel(q){
 $$('.explanation,details,.question-img').forEach(e=>e.style.display='none');$('#recall-area').innerHTML=`<p class="small muted" style="margin:12px 0">解析和题图暂时遮住。用自己的话写：关键条件 → 关键转折 → 为什么这样做。然后试着在纸上重做。</p><div class="field"><textarea id="recall-text" placeholder="这道题真正的关键是…，因为…">${esc(session.responses[q.id]?.reflection||'')}</textarea></div><button id="save-recall" class="btn small">保存闭卷复述</button><button id="restore-explanation" class="linkbutton" style="margin-left:10px">再次核对解析</button>`;
 on('#save-recall','click',async()=>{const text=$('#recall-text').value;await act({type:'reflection',attemptId:session.responses[q.id].id,text});session.responses[q.id]=state.attempts.find(a=>a.id===session.responses[q.id].id);saveSession();toast('复述已保存。明天用同考点新题，检查是否真正吸收。');});
 on('#restore-explanation','click',()=>{$$('.explanation,details,.question-img').forEach(e=>e.style.display='');});
}

function syncWallpaper(){const v=$('#wallpaper');if(!v)return;const motion=(localStorage.getItem('eju-wallpaper')||'motion')==='motion'&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.hidden&&!$('.modal');if(motion){v.muted=true;v.play().catch(()=>{});}else v.pause();}
document.addEventListener('visibilitychange',syncWallpaper);matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',syncWallpaper);

document.documentElement.dataset.theme=localStorage.getItem('eju-theme')||'sage';

async function runCoach(input,target,button){const b=$(button);if(b)b.disabled=true;let job;try{job=await request('/api/ai/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});if(input.type==='plan')localStorage.setItem('eju-plan-job',job.id);const started=Date.now();while(job.status==='running'){if($(target)){$(target).innerHTML=`<div class="note" style="margin-top:12px">Codex 正在思考 · ${Math.floor((Date.now()-started)/1000)} 秒 <button class="linkbutton" id="cancel-coach">取消</button></div>`;on('#cancel-coach','click',()=>request('/api/ai/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:job.id})}));}await new Promise(r=>setTimeout(r,1000));job=await request('/api/ai/job?id='+encodeURIComponent(job.id));}if(job.status!=='completed')throw Error(job.error||'本次请求没有完成。');return job.result;}catch(e){if($(target))$(target).innerHTML=`<div class="note warm" style="margin-top:12px">${esc(e.message)}</div>`;else toast(e.message);return null;}finally{if(b?.isConnected)b.disabled=false;}}
function renderAIPlan(result){if(!$('#ai-plan-result'))return;const p=result.plan;$('#ai-plan-result').innerHTML=`<div class="note" style="margin:16px 0;white-space:pre-wrap">${esc(result.diagnosis)}</div><h3>${esc(p.fromDate)} · ${sum(Object.values(p.allocations))} 分钟</h3><div class="row" style="margin:12px 0">${Object.entries(p.allocations).map(([k,v])=>`<span class="tag">${SUBJECTS[k]} ${v} 分钟</span>`).join('')}</div><p class="small muted">${esc(p.note)}</p><button class="btn" id="ai-plan-apply" style="margin-top:18px">应用这份明日计划</button>`;on('#ai-plan-apply','click',async()=>{await act({type:'coach',plan:p});closeModal();toast('Codex 建议已应用，明天按新题单学习。');});}
function aiPlanDialog(){openModal('Codex 学习教练',`<p>结合今天的作答、卡点和疲劳情况，调整明天的学习。</p><div class="row" style="margin:18px 0"><button id="ai-plan-run" class="btn">分析今日汇报</button>${localStorage.getItem('eju-plan-job')?'<button id="ai-plan-last" class="btn line">查看上次建议</button>':''}</div><div id="ai-plan-result"></div><details><summary>发送哪些资料</summary><p class="small muted">学习背景、科目基线、近7天正确率、错题与提示记录、你的复盘和写作草稿。使用当前 Codex 登录及额度；不会自动应用建议。</p></details>`);on('#ai-plan-run','click',async()=>{const r=await runCoach({type:'plan'},'#ai-plan-result','#ai-plan-run');if(r)renderAIPlan(r);});on('#ai-plan-last','click',async()=>{const j=await request('/api/ai/job?id='+localStorage.getItem('eju-plan-job'));if(j.status==='completed')renderAIPlan(j.result);else $('#ai-plan-result').textContent=j.error||'还在处理，可以稍后再查看。';});}
